<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\HttpException;
use Sentinel\Tests\FieldFixture;
final class BusinessOperationsTest extends TestCase
{
    private function rejects(callable $fn,int $status):void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
    private function fixture():array {[$app,$db,$ctx]=FieldFixture::create();$db->execute('CREATE TABLE contracts(contract_id INTEGER PRIMARY KEY,company_id INTEGER,client_id INTEGER,contract_number TEXT,contract_name TEXT,start_date TEXT,end_date TEXT,monthly_value TEXT,required_guard_count INTEGER,shift_requirements_json TEXT,status TEXT,deleted_at TEXT,updated_by_user_id INTEGER)');$db->execute("INSERT INTO contracts VALUES(1,101,1,'C1','Gate','2025-01-01',:end,'1000.00',1,'{}','ACTIVE',NULL,1)",['end'=>gmdate('Y-m-d',time()-86400)]);return [$app,$db,$ctx];}
    public function testSponsorOnlyExplicitFreeAndNoPaidTrialOrExpiredAds():void {
        [$app,$db]=$this->fixture();$db->execute('CREATE TABLE company_subscriptions(company_id INTEGER,plan_code TEXT,subscription_status TEXT,trial_ends_at TEXT,current_period_ends_at TEXT)');$app->config()->set('sponsors.enabled',true);$app->config()->set('sponsors.campaign',['id'=>'own','title'=>'Sponsor','body'=>'Own banner','cta'=>'Visit','url'=>'https://example.test/sponsor']);$s=$app->container()->make('sponsor_service');self::assertFalse($s->placement()['enabled']);
        foreach(['FREE','ESSENTIAL','PROFESSIONAL','ENTERPRISE','UNKNOWN']as$plan)foreach(['ACTIVE','TRIALING','EXPIRED','CANCELLED']as$status){$db->execute('DELETE FROM company_subscriptions');$db->execute('INSERT INTO company_subscriptions VALUES(101,:plan,:status,NULL,NULL)',compact('plan','status'));self::assertSame($plan==='FREE',$s->placement()['enabled'],$plan.' '.$status);}
        $db->execute("UPDATE company_subscriptions SET plan_code='FREE'");foreach(['javascript:alert(1)','//evil.test','/\\evil.test','http://example.test','https://user:pass@example.test']as$url){$app->config()->set('sponsors.campaign.url',$url);self::assertFalse($s->placement()['enabled']);}$app->config()->set('sponsors.campaign.url','/admin/index.html#company-workspace');self::assertTrue($s->placement()['enabled']);$app->config()->set('sponsors.enabled',false);self::assertFalse($s->placement()['enabled']);
    }
    public function testVisitorClientApprovalOneUseIdentityAndCurrentMapping():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$s=$app->container()->make('visitor_appointment_service');$id=$s->create(['site_id'=>1,'visitor_name'=>'Visitor','purpose'=>'Delivery','arrival_from'=>gmdate('Y-m-d H:i:s',time()-60),'departure_due'=>gmdate('Y-m-d H:i:s',time()+3600)])['id'];$this->rejects(fn()=>$s->approve($id,['expected_revision'=>1]),404);$ctx->setUser('2');$pass=$s->approve($id,['expected_revision'=>1])['pass'];self::assertStringNotContainsString($pass,json_encode($s->list(['site_id'=>1],true)));self::assertNotSame($pass,$db->fetch('SELECT pass_hash FROM visitor_appointments')['pass_hash']);$ctx->setUser('1');$body=['site_id'=>1,'pass'=>$pass,'identity_checked'=>true];$this->rejects(fn()=>$s->checkIn([...$body,'identity_checked'=>false]),422);$this->rejects(fn()=>$s->checkIn([...$body,'site_id'=>2]),404);self::assertTrue($s->checkIn($body)['checked_in']);$this->rejects(fn()=>$s->checkIn($body),409);self::assertSame('CHECKED_OUT',$s->transition($id,'checkout',['expected_revision'=>3])['state']);self::assertSame(2,(int)$db->fetch('SELECT COUNT(*) AS n FROM gate_register')['n']);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$ctx->setUser('2');$this->rejects(fn()=>$s->list(['site_id'=>1],true),404);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->transition($id,'cancel',['expected_revision'=>4]),404);
    }
    private function vehicle($s):string {return $s->create(['site_id'=>1,'registration'=>'TEST123','description'=>'Patrol vehicle','odometer_km'=>100,'next_service_km'=>1000,'next_service_on'=>gmdate('Y-m-d',time()+86400*30)])['id'];}
    private function trip($s,string $id,int $employee=2):string {return $s->allocate($id,['employee_id'=>$employee,'starts_at'=>gmdate('Y-m-d H:i:s',time()-60),'ends_at'=>gmdate('Y-m-d H:i:s',time()+3600),'purpose'=>'Patrol'])['id'];}
    private function checks():array {return array_fill_keys(['brakes','tyres','lights','seatbelts','fluid_levels'],true);}
    public function testFleetOverlapsDriverOwnershipMileageFuelAndService():void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('fleet_operations_service');$id=$this->vehicle($s);$trip=$this->trip($s,$id);$this->rejects(fn()=>$this->trip($s,$id),409);$this->rejects(fn()=>$s->tripAction($trip,'start',['expected_revision'=>1,'odometer_km'=>100,'checks'=>$this->checks()],true),404);$ctx->setUser('2');self::assertSame('IN_PROGRESS',$s->tripAction($trip,'start',['expected_revision'=>1,'odometer_km'=>100,'checks'=>$this->checks()],true)['state']);$this->rejects(fn()=>$s->tripAction($trip,'finish',['expected_revision'=>2,'odometer_km'=>99],true),422);self::assertSame('COMPLETED',$s->tripAction($trip,'finish',['expected_revision'=>2,'odometer_km'=>150],true)['state']);$ctx->setUser('1');$s->fuel($id,['odometer_km'=>150,'litres_milli'=>12500,'cost_minor'=>30000,'currency'=>'ZAR','receipt_reference'=>'Receipt 1']);$trip=$this->trip($s,$id);self::assertSame('CHECK_FAILED',$s->tripAction($trip,'start',['expected_revision'=>1,'odometer_km'=>151,'checks'=>[...$this->checks(),'brakes'=>false]])['state']);$this->rejects(fn()=>$this->trip($s,$id),409);self::assertSame('GROUNDED',$s->list(['site_id'=>1])[0]['state']);$s->service($id,['odometer_km'=>151,'next_service_km'=>2000,'next_service_on'=>gmdate('Y-m-d',time()+86400*90),'evidence_reference'=>'Workshop repair 1']);self::assertSame('ACTIVE',$s->list(['site_id'=>1])[0]['state']);self::assertCount(1,$s->list(['site_id'=>1])[0]['services']);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->allocate($id,[]),404);
    }
    private function renewal($s):string {return $s->propose(['contract_id'=>1,'starts_on'=>gmdate('Y-m-d'),'ends_on'=>gmdate('Y-m-d',time()+86400*365),'monthly_minor'=>123456,'currency'=>'ZAR','terms'=>'Agreed guarding service'])['id'];}
    public function testRenewalClientDecisionScheduledEffectHistoryAndIdempotence():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$s=$app->container()->make('contract_renewal_service');$id=$this->renewal($s);$hash=$s->list()[0]['offer_hash'];$this->rejects(fn()=>$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Approved']),404);$ctx->setUser('2');$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Approved']);self::assertSame('1000.00',$db->fetch('SELECT monthly_value FROM contracts')['monthly_value']);$ctx->setUser('1');$s->schedule($id,['expected_revision'=>2]);self::assertSame(['applied'=>1,'blocked'=>0],$s->applyDue());self::assertSame('1234.56',$db->fetch('SELECT monthly_value FROM contracts')['monthly_value']);self::assertSame(['applied'=>0,'blocked'=>0],$s->applyDue());self::assertSame('1000.00',json_decode($s->list()[0]['history'][0]['before_json'],true)['monthly_value']);
    }
    public function testRenewalRejectsChangedTermsAndChangedOriginalContract():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$s=$app->container()->make('contract_renewal_service');$id=$this->renewal($s);$hash=$s->list()[0]['offer_hash'];$db->execute('UPDATE contract_renewals SET monthly_minor=999999');$ctx->setUser('2');$this->rejects(fn()=>$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Approved']),409);$db->execute('UPDATE contract_renewals SET monthly_minor=123456');$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Approved']);$ctx->setUser('1');$s->schedule($id,['expected_revision'=>2]);$db->execute("UPDATE contracts SET monthly_value='2000.00'");self::assertSame(['applied'=>0,'blocked'=>1],$s->applyDue());self::assertSame('2000.00',$db->fetch('SELECT monthly_value FROM contracts')['monthly_value']);
    }
    public function testEncryptedBackupRoundTripTenantIsolationCorruptionAndRetention():void {
        [$app,$db,$ctx]=$this->fixture();$dir=sys_get_temp_dir().'/sentinel-backup-test-'.uuid4();$app->config()->set('backups.encryption_key',str_repeat('fixture-key-',4));$app->config()->set('backups.directory',$dir);$app->config()->set('backups.max_bytes',10000000);$db->execute('CREATE TABLE binary_fixture(company_id INTEGER,payload BLOB,amount REAL,missing TEXT)');$payload="sensitive tenant bytes".chr(0).chr(255);$stmt=$db->connection()->prepare('INSERT INTO binary_fixture VALUES(101,?,1.25,NULL),(202,?,2.5,NULL)');$stmt->execute([$payload,'other tenant']);$s=$app->container()->make('encrypted_backup_service');
        try{$s->schedule(['expected_revision'=>0,'enabled'=>true,'interval_hours'=>24,'retain_count'=>2]);for($i=0;$i<3;$i++){$s->request();$result=$s->runDue();self::assertFalse($result['failed'],json_encode($s->overview()));self::assertTrue($result['restore']['passed']);self::assertSame('ISOLATED_DATA_ROUND_TRIP',$result['restore']['test_type']);}self::assertCount(2,glob($dir.'/*.snb'));self::assertSame([],glob($dir.'/restore-test-*'));$jobs=$s->overview()['jobs'];self::assertSame('PRUNED',$jobs[2]['state']);$job=$db->fetch('SELECT * FROM encrypted_backups WHERE backup_id=:id',['id'=>$jobs[0]['backup_id']]);$path=$dir.'/101-'.$job['artifact_uuid'].'.snb';$cipher=file_get_contents($path);self::assertStringNotContainsString('sensitive tenant bytes',$cipher);self::assertStringNotContainsString('other tenant',$cipher);file_put_contents($path,substr($cipher,0,-1).'X');self::assertFalse($s->verify((string)$job['backup_id'])['passed']);self::assertSame(1.25,(float)$db->fetch('SELECT amount FROM binary_fixture WHERE company_id=101')['amount']);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->verify((string)$job['backup_id']),404);
        }finally{foreach(glob($dir.'/*')?:[]as$f)unlink($f);if(is_dir($dir))rmdir($dir);}
    }
    public function testBackupRefusesPublicDirectoryAndMarksStorageFailure():void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('encrypted_backup_service');$this->rejects(fn()=>$s->request(),422);$app->config()->set('backups.encryption_key',str_repeat('x',32));$app->config()->set('backups.directory',dirname(__DIR__,2).'/public');$this->rejects(fn()=>$s->schedule(['expected_revision'=>0,'enabled'=>true,'interval_hours'=>24,'retain_count'=>2]),422);$s->request();self::assertTrue($s->runDue()['failed']);self::assertSame('FAILED',$s->overview()['jobs'][0]['state']);
    }
    public function testPilotRolesRequireMfaAndDemoDoesNotPolluteOperations():void {
        [$app,$db,$ctx]=$this->fixture();foreach(['role_name TEXT','role_description TEXT','is_system_role INTEGER']as$c)$db->execute('ALTER TABLE roles ADD COLUMN '.$c);$s=$app->container()->make('pilot_setup_service');$this->rejects(fn()=>$s->role(['template_code'=>'GUARD']),403);$ctx->setMfaVerified(true);$created=$s->role(['template_code'=>'GUARD']);self::assertSame($created['role_id'],$s->role(['template_code'=>'GUARD'])['role_id']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM user_roles WHERE role_id=:id',['id'=>$created['role_id']])['n']);$s->demo();$s->demo();self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM pilot_demo_records')['n']);foreach(['incidents','visitor_appointments','fleet_vehicles','contract_renewals']as$t)self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM '.$t)['n']);self::assertFalse($s->overview()['technical_checks_passed']);
    }
    public function testOffersRequireAcceptanceManagerAwardAndEligibilityRecheck():void {
        [$app,$db,$ctx]=$this->fixture();foreach(['position_id INTEGER','assignment_status TEXT','deleted_at TEXT']as$c)$db->execute('ALTER TABLE employee_assignments ADD COLUMN '.$c);$db->execute('CREATE TABLE positions(position_id INTEGER PRIMARY KEY,company_id INTEGER,position_category TEXT,position_status TEXT,deleted_at TEXT)');$db->execute("INSERT INTO positions VALUES(1,101,'GUARD','ACTIVE',NULL)");$db->execute("INSERT INTO employee_assignments VALUES(1,101,1,1,'ACTIVE',NULL),(2,101,2,1,'ACTIVE',NULL)");$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(1,101,1,1,:start,:end,'ASSIGNED')",['start'=>gmdate('Y-m-d H:i:s',time()+3600),'end'=>gmdate('Y-m-d H:i:s',time()+7200)]);$s=$app->container()->make('open_shift_offer_service');$id=$s->broadcast(['shift_id'=>1,'deadline_at'=>gmdate('Y-m-d H:i:s',time()+1800)])['id'];$this->rejects(fn()=>$s->award($id,['expected_revision'=>1,'employee_id'=>2,'reason'=>'Manager approval']),409);$ctx->setUser('2');self::assertFalse($s->accept($id)['assigned']);self::assertSame(1,(int)$db->fetch('SELECT employee_id FROM shift_assignments')['employee_id']);$db->execute("UPDATE employees SET employment_status='INACTIVE' WHERE employee_id=2");$ctx->setUser('1');$this->rejects(fn()=>$s->award($id,['expected_revision'=>1,'employee_id'=>2,'reason'=>'Manager approval']),409);$db->execute("UPDATE employees SET employment_status='ACTIVE' WHERE employee_id=2");self::assertTrue($s->award($id,['expected_revision'=>1,'employee_id'=>2,'reason'=>'Manager confirmed availability'])['assigned']);self::assertSame(2,(int)$db->fetch('SELECT employee_id FROM shift_assignments')['employee_id']);$this->rejects(fn()=>$s->award($id,['expected_revision'=>1,'employee_id'=>2,'reason'=>'Repeat']),409);
    }
    public function testRemindersDeduplicateResolveAndDoNotLeakToRestrictedRecipients():void {
        [$app,$db]=$this->fixture();$pilot=$app->container()->make('pilot_setup_service');$pilot->settings(['reminder_user_id'=>1,'expected_revision'=>0]);$fleet=$app->container()->make('fleet_operations_service');$this->vehicle($fleet);$db->execute("UPDATE fleet_vehicles SET next_service_km=100");$r=$app->container()->make('business_reminder_service');self::assertSame(2,$r->tick()['reminders']);self::assertSame(0,$r->tick()['reminders']);self::assertSame(2,(int)$db->fetch("SELECT COUNT(*) AS n FROM notifications WHERE event_type='BUSINESS_OPERATIONS_REMINDER'")['n']);$db->execute('UPDATE fleet_vehicles SET next_service_km=1000');$r->tick();self::assertSame('RESOLVED',$db->fetch("SELECT state FROM business_reminders WHERE source_key LIKE 'fleet:%'")['state']);$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(1,9001,101)');$db->execute('UPDATE fleet_vehicles SET next_service_km=100');self::assertSame(1,$r->tick()['reminders']);self::assertSame(2,(int)$db->fetch("SELECT COUNT(*) AS n FROM notifications WHERE event_type='BUSINESS_OPERATIONS_REMINDER'")['n']);
    }
}
